/* Admin console tests: roles, maker-checker, audit, sections, segments, shared state. */
const as=n=>{A.who=n;A.role=DB().staff.find(s=>s.name===n).role};const fresh0=()=>{BOCStore.reset();as("Priya");A.section="users";A.sel=null;A.q="";A.seg={model:"",city:"",plan:"",verified:""};render()};
test("Marketing sees only its four sections",()=>{fresh0();as("Tanvi");render();const labels=[...document.querySelectorAll("#nav button span:first-child")].map(s=>s.textContent);eq(labels,["Ads","Broadcasts","Reports","Features and limits"])});
test("suspend waits for a second admin",()=>{fresh0();as("Imran");const x=doAct("suspend","qd");eq(x.status,"awaiting approval");eq(DB().businesses.find(b=>b.key==="qd").status,"active")});
test("nobody approves their own request, Super admin included",()=>{fresh0();const x=doAct("suspend","qd");eq(approve(x.id,"Priya").ok,false);eq(approve(x.id,"Arun").ok,true);fresh0();const y=doAct("suspend","qd");as("Imran");eq(approve(y.id,"Priya").ok,false);eq(DB().businesses.find(b=>b.key==="qd").status,"active")});
test("another admin approves and it applies, with two audit entries",()=>{fresh0();as("Imran");const x=doAct("suspend","qd");eq(approve(x.id,"Priya").ok,true);eq(DB().businesses.find(b=>b.key==="qd").status,"suspended");eq(DB().audit.length,2)});
test("GSTIN search finds Shree Textiles",()=>{fresh0();A.q="33ABHFS4821K1Z6";render();ok(document.getElementById("main").textContent.includes("Shree Textiles"));ok(!document.getElementById("main").textContent.includes("Glow Studio"))});
test("segment filters combine with AND",()=>{fresh0();eq(segCount(DB(),{model:"",city:"Ludhiana",plan:"free",verified:""}),1);eq(segCount(DB(),{model:"",city:"Ludhiana",plan:"pro",verified:""}),0);eq(segCount(DB(),{model:"B2B",city:"",plan:"",verified:"yes"}),4)});
test("ticket without access hides the chat",()=>{fresh0();A.section="support";A.sel="TK-1041";render();ok(document.getElementById("main").textContent.includes("Chats stay private"));A.sel="TK-1042";render();ok(document.getElementById("main").textContent.includes("shared this chat"))});
test("dispute split 60/40 after approval",()=>{fresh0();as("Vikram");const x=doAct("split","DP-0031",{buyerPct:60});approve(x.id,"Priya");const d=DB().disputes[0];eq(d.status,"resolved");ok(d.outcome.includes("buyer ₹1,440")&&d.outcome.includes("seller ₹960"),d.outcome)});
test("feature override lands in shared flags",()=>{fresh0();A.ft={target:"list",key:"items",value:"200",list:["ld"]};H.applyft();eq(DB().flags.ld.items,200)});
test("writes reach a subscriber (two tabs)",async()=>{fresh0();let got=null;BOCStore.subscribe(s=>got=s);
  /* storage events fire only in other tabs, so simulate one */
  const s=BOCStore.load()||{};s.admin=DB();s.admin.ads[1].status="live";localStorage.setItem(BOCStore.KEY,JSON.stringify(s));window.dispatchEvent(new StorageEvent("storage",{key:BOCStore.KEY}));await wait(10);ok(got&&got.admin.ads[1].status==="live");BOCStore.reset()});
test("every section renders for Super admin",()=>{fresh0();Object.keys(SECTIONS).forEach(k=>{A.section=k;A.sel=null;render();ok(document.getElementById("main").innerHTML.length>200,k)});BOCStore.reset()});

test("release needs approval and a settled dispute cancels later requests",()=>{fresh0();as("Vikram");const r=doAct("refund","DP-0031");const l=doAct("release","DP-0031");eq(l.status,"awaiting approval");eq(approve(l.id,"Priya").ok,true);const held=DB().escrow.held;eq(approve(r.id,"Priya").ok,false);eq(DB().escrow.held,held);eq(DB().disputes[0].outcome,"Released to seller");BOCStore.reset()});
